-- Филиалы — отдельные вузы со своим приёмом, а не программы головного вуза.
-- Парсер датасета A читал их вместе с головным вузом, и сид сворачивал их
-- льготы в льготы вуза: в карточке ВШЭ льгота нижегородской программы
-- выглядела как московская (Всесибирская по физике на 01.03.01 — БВИ, хотя в
-- Москве только 100 баллов победителю), у МГУ — льготы филиалов в Грозном и
-- Севастополе, у КФУ — Елабужского и Набережночелнинского институтов и филиала
-- в Джизаке. Теперь в каталоге только головные вузы: у ВШЭ — Москва, у МГУ и
-- КФУ секции филиалов не читаются. У Сеченова ушли конкурсные группы для
-- иностранных граждан — не для школьников из России.
-- Парсер исправлен, A, B и сиды 0003 и 0021 пересобраны — здесь та же разница
-- для накатанных баз.
--
-- Триггер 0006 запишет события там, где льгота вуза правда поменялась:
-- семьи, которые следят за этими вузами, узнают об исправлении. У
-- direction_benefits триггеров нет. Выбор пар вуз–направление, которых больше
-- нет, снимается каскадом; направление и вуз в цели ученика остаются.
-- Из списка направлений вуза уходят те, что держались на филиалах. Направления,
-- у которых не осталось программ (психология, социология, педагогическое
-- образование, профессиональное обучение), удаляются, только если их не выбрал
-- ни один ученик.
--
-- Льготы по вузам: удаляется 87, добавляется или меняется 148.
-- Льготы по направлениям: удаляется 1358, добавляется или меняется 734.
-- Пары вуз–направление: удаляется 10, добавляется или меняется 25. Источников новых 20.
--
-- Сгенерировано datasets/parser/diff_seed.py; эквивалентность сиду — make test-db.

-- +goose Up

