  ('p669-65-informatika', 'msu', 'napr-38-03-02', 2026, 'score100', 75, ARRAY[11], 'Зависит от программы: на «Менеджмент» (Факультет государственного управления) и «Менеджмент — Управление бизнесом и предпринимательство» льготы нет. Подтвердить ЕГЭ: Информатика', true, 'src-8356fd88d26d'),
  ('p669-75-matematika', 'msu', 'napr-38-03-02', 2026, 'bvi_winners', 75, ARRAY[11], 'Зависит от программы: на «Менеджмент» (Высшая школа современных социальных наук), «Менеджмент» (Факультет государственного управления) и «Менеджмент — Управление бизнесом и предпринимательство» — 100 баллов, на «Менеджмент — Менеджмент в культуре» льготы нет. Победителю — БВИ, призёру — 100 баллов. Подтвердить ЕГЭ: Математика', true, 'src-9aef2708ec32'),
  ('p669-8-ekonomika', 'msu', 'napr-38-03-02', 2026, 'bvi_winners', 75, ARRAY[11], 'Зависит от программы: на «Менеджмент — Управление бизнесом и предпринимательство» — 100 баллов, на «Менеджмент» (Высшая школа современных социальных наук), «Менеджмент» (Факультет государственного управления) и «Менеджмент — Менеджмент в культуре» льготы нет. Победителю — БВИ, призёру — 100 баллов. Подтвердить ЕГЭ: Математика', true, 'src-9aef2708ec32'),
  ('p669-8-matematika', 'msu', 'napr-38-03-02', 2026, 'bvi_winners', 75, ARRAY[11], 'Зависит от программы: на «Менеджмент» (Высшая школа современных социальных наук), «Менеджмент» (Факультет государственного управления) и «Менеджмент — Управление бизнесом и предпринимательство» — 100 баллов, на «Менеджмент — Менеджмент в культуре» льготы нет. Победителю — БВИ, призёру — 100 баллов. Подтвердить ЕГЭ: Математика', true, 'src-9aef2708ec32'),
